"""Compare new vs original on random problems; report timing."""
import sys, time, warnings
import numpy as np
import scipy.sparse as sp
warnings.simplefilter("ignore")
import origcd
O = origcd.orig
import sklearn.linear_model as N

def mk(rng, n, p, k=1, density=None):
    if density is None:
        X = rng.standard_normal((n, p))
    else:
        X = sp.random(n, p, density=density, format="csc", random_state=rng) * 3
        X.data += rng.standard_normal(X.data.shape)
    w = np.zeros((p, k)); m = max(1, p // 10)
    w[:m] = rng.standard_normal((m, k))
    y = X @ w + 0.1 * rng.standard_normal((n, k)) + rng.standard_normal()
    return X, (y[:, 0] if k == 1 else y)

def chk(name, a, b, rel=1e-6):
    a = np.asarray(a, dtype=float); b = np.asarray(b, dtype=float)
    assert a.shape == b.shape, (name, a.shape, b.shape)
    m = np.max(np.abs(a)) if a.size else 0
    d = np.max(np.abs(a - b)) if a.size else 0
    ok = d <= rel * m
    if not ok:
        print(f"   MISMATCH {name}: diff={d:.3g} max={m:.3g}")
    return ok

def run_case(kind, seed):
    rng = np.random.default_rng(seed)
    tol = rng.uniform(1e-3, 5e-3); nal = int(rng.integers(60, 401))
    l1 = float(rng.choice([1.0, 0.5, 0.8, 0.2]))
    res = []
    if kind in ("dense_path", "dense_lasso_path"):
        n = int(rng.integers(500, 8000)); p = int(rng.integers(10, 200))
        X, y = mk(rng, n, p)
        X = np.asfortranarray(X - X.mean(0)); y = y - y.mean()
        f = "enet_path" if kind == "dense_path" else "lasso_path"
        kw = dict(alphas=nal, tol=tol, precompute=False, return_n_iter=True)
        if f == "enet_path": kw["l1_ratio"] = l1
        def call(M):
            return getattr(M, f)(X, y, **kw)
        return call, ("alphas", "coefs", "gaps", "niter")
    if kind == "gram":
        n = int(rng.integers(300, 3000)); p = int(rng.integers(20, n))
        p = min(p, 1500)
        X, y = mk(rng, n, p)
        X = np.asfortranarray(X - X.mean(0)); y = y - y.mean()
        G = X.T @ X; Xy = X.T @ y
        def call(M):
            return M.enet_path(X, y, l1_ratio=l1, precompute=G, Xy=Xy, alphas=nal, tol=tol, return_n_iter=True)
        return call, ("alphas", "coefs", "gaps", "niter")
    # CV estimators
    sw = None
    if kind.startswith("mt_"):
        n = int(rng.integers(200, 2500)); p = int(rng.integers(10, 150)); k = int(rng.integers(2, 5))
        X, y = mk(rng, n, p, k, density=float(rng.uniform(0.02, 0.3)))
        cls = "MultiTaskElasticNetCV" if rng.random() < 0.5 else "MultiTaskLassoCV"
    elif kind.startswith("sp_"):
        n = int(rng.integers(200, 4000)); p = int(rng.integers(10, 300))
        X, y = mk(rng, n, p, density=float(rng.uniform(0.01, 0.3)))
        cls = "ElasticNetCV" if rng.random() < 0.5 else "LassoCV"
    else:  # dense_cv
        n = int(rng.integers(500, 6000)); p = int(rng.integers(10, 150))
        X, y = mk(rng, n, p)
        cls = "ElasticNetCV" if rng.random() < 0.5 else "LassoCV"
    fi = bool(rng.random() < 0.5)
    if rng.random() < 0.5:
        sw = rng.uniform(0.1, 3, size=X.shape[0])
        sw[rng.random(X.shape[0]) < 0.1] = 0
    kw = dict(alphas=nal, cv=3, tol=tol, fit_intercept=fi)
    if kind == "dense_cv": kw["precompute"] = False; sw = None if rng.random() < .5 else sw
    if "ElasticNet" in cls: kw["l1_ratio"] = [l1, 0.9] if rng.random() < 0.3 else l1
    def call(M):
        e = getattr(M, cls)(**kw).fit(X, y, sample_weight=sw)
        return (e.coef_, e.intercept_, e.mse_path_, e.dual_gap_, e.n_iter_, e.alpha_, getattr(e, "l1_ratio_", 1.0), e.alphas_)
    return call, ("coef", "intercept", "mse", "gap", "niter", "alpha", "l1r", "alphas")

def compare(kind, seed):
    call, names = run_case(kind, seed)
    t = time.perf_counter(); a = call(O); to = time.perf_counter() - t
    t = time.perf_counter(); b = call(N); tn = time.perf_counter() - t
    ok = True
    for nm, x, y in zip(names, a, b):
        if nm == "niter":
            if list(np.ravel(x)) != list(np.ravel(y)):
                print(f"   MISMATCH niter {np.ravel(x)[:10]} vs {np.ravel(y)[:10]}"); ok = False
        elif nm in ("alphas", "alpha", "l1r"):
            ok &= chk(nm, x, y, 1e-9)
        else:
            ok &= chk(nm, x, y)
    return ok, to, tn

if __name__ == "__main__":
    kinds = sys.argv[1].split(",")
    seeds = range(int(sys.argv[2]), int(sys.argv[3]))
    for kind in kinds:
        To = Tn = 0; bad = 0
        for s in seeds:
            ok, to, tn = compare(kind, s)
            To += to; Tn += tn; bad += not ok
            if not ok: print(f"  {kind} seed {s} FAILED")
        print(f"{kind:18s} orig {To:7.2f}s new {Tn:7.2f}s speedup {To/Tn:5.2f}  bad={bad}")
